-- 1. 在 HMS 后端 MySQL 上看真实慢 SQL（最常见 bottleneck）
SELECT COUNT(*) FROM PARTITIONS;        -- 分区行数过亿就要警惕
SHOW INDEX FROM PARTITIONS;              -- 必须有 (TBL_ID, PART_NAME) 联合索引
SHOW INDEX FROM PARTITION_KEY_VALS;

-- 2. 在 Hive/Spark 端打开 direct SQL，绕开 DataNucleus ORM
SET hive.metastore.try.direct.sql=true;
SET hive.metastore.try.direct.sql.ddl=true;

-- 3. 用 EXPLAIN 验证分区裁剪是否真的下推到 HMS
EXPLAIN EXTENDED
SELECT user_id FROM ods.user_event
WHERE dt='2026-06-13' AND hour='10';
-- 关注 'Partition Filter Operator' 是否出现，以及读到的 partition 数量

-- 4. 更新统计信息，修复优化器选错 join 计划
ANALYZE TABLE ods.user_event PARTITION(dt='2026-06-13')
  COMPUTE STATISTICS FOR COLUMNS user_id, event_type;
DESCRIBE FORMATTED ods.user_event PARTITION(dt='2026-06-13');  -- 看 numRows / numFiles

-- 5. 数据被 Spark 直接写到 S3 但 HMS 没注册时
MSCK REPAIR TABLE ods.user_event SYNC PARTITIONS;
